import re, pathlib

p=pathlib.Path('app.js')
s=p.read_text(encoding='utf-8')

home=r'''function home(){const chosen=state.selfReportedWeak||AREAS[0];const detected=AREAS.slice().sort((a,b)=>state.difficultyScores[a]-state.difficultyScores[b])[0];const ordered=[chosen,...AREAS.filter(a=>a!==chosen).sort((a,b)=>state.difficultyScores[a]-state.difficultyScores[b])];const daily=Math.min(100,pct(state.dailyXp,60));return `<section class="hero"><span class="eyebrow">${esc(state.goal)}</span><h1>Seu estudo, do seu jeito.</h1><p>O EstudAI dá mais atenção ao foco que você escolheu e usa seu desempenho para sugerir reforços, sem abandonar as outras áreas.</p><div class="hero-actions"><button class="primary" data-action="personal-study">▶ Estudo personalizado</button><button class="secondary" data-tab="redacao">✍ Treinar redação</button></div><div class="goal"><div><b>Meta de hoje</b><strong>${daily}%</strong></div><div class="progress"><i style="width:${daily}%"></i></div><small>${state.dailyXp}/60 XP hoje</small></div></section><section><div class="title-row focus-title"><h2>Foco recomendado</h2><span>personalizado para você</span></div><div class="focus-note"><b>🎯 Seu foco escolhido: ${chosen}</b>${detected!==chosen?`<span>🔎 Seu desempenho também indica reforço em ${detected}.</span>`:`<span>Seu desempenho confirma essa prioridade.</span>`}</div><div class="focus-grid">${ordered.map((a,i)=>`<article class="focus-card tone-${i}"><div class="focus-icon">${['📖','🌎','🧪','📐'][AREAS.indexOf(a)]}</div><div><small>${i===0?'PRIORIDADE ESCOLHIDA':(a===detected?'PONTO FRACO DETECTADO':'REVISÃO')}</small><h3>${a}</h3><p>${state.difficultyScores[a]}% de domínio estimado</p></div><button data-action="area-study" data-area="${a}">Praticar →</button></article>`).join('')}</div></section>`}'''
s,n=re.subn(r'function home\(\)\{.*?\}\n\nfunction desempenho',home+'\n\nfunction desempenho',s,count=1,flags=re.S)
if n!=1: raise SystemExit('home patch failed')

essay=r'''
const ESSAY_STOP=new Set('para pela pelo pelas pelos uma umas uns como com sem sobre entre mais menos muito muita muitos muitas ainda isso essa esse essas esses deste desta dessa desse onde quando quem qual quais seus suas nosso nossa nossos nossas brasil brasileira brasileiro desafio desafios caminhos medidas impactos perspectivas papel forma meio meio'.split(' '));
function essayTokens(x){return String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(w=>w.length>4&&!ESSAY_STOP.has(w))}
function essayThemeMatch(text){const tk=[...new Set(essayTokens(state.theme))],tw=new Set(essayTokens(text));const hits=tk.filter(k=>tw.has(k));return{keywords:tk,hits,ratio:tk.length?hits.length/tk.length:0}}
function scoreEssay(text){const wc=countWords(text),parts=text.split(/\n+/).map(x=>x.trim()).filter(Boolean),pars=parts.length,low=text.toLowerCase(),sentences=text.split(/[.!?]+/).map(x=>x.trim()).filter(Boolean),connectors=['além disso','portanto','entretanto','contudo','assim','dessa forma','nesse sentido','por conseguinte','todavia','desse modo'].filter(x=>low.includes(x)),agent=['governo','estado','escola','sociedade','ministério','prefeitura','família','empresas'].find(x=>low.includes(x)),action=['deve','promover','criar','implementar','ampliar','garantir','fiscalizar','investir'].find(x=>low.includes(x)),tm=essayThemeMatch(text),tips=[],strengths=[],errors=[];if(wc<40)return{total:0,comp:[0,0,0,0,0],tips:['Desenvolva uma redação completa antes da correção.'],strengths:[],errors:['Texto insuficiente para avaliar as cinco competências.'],offTopic:false,themeCoverage:0};const offTopic=tm.keywords.length>=2&&tm.hits.length===0;const weakTheme=!offTopic&&tm.keywords.length>=3&&tm.ratio<0.3;if(offTopic)return{total:0,comp:[0,0,0,0,0],tips:[`Reescreva o texto mantendo a discussão centrada em “${state.theme}”.`,`Use os conceitos centrais do tema ao longo da tese, dos argumentos e da intervenção.`],strengths:wc>=200?['Você produziu um texto com extensão suficiente para desenvolver uma argumentação.']:[],errors:[`Fuga ao tema: não encontrei relação suficiente entre o texto e “${state.theme}”.`],offTopic:true,themeCoverage:0};let c1=wc>=260?180:wc>=180?160:120,c2=weakTheme?80:tm.ratio>=0.5?180:160,c3=pars>=4&&sentences.length>=8?180:pars>=3?160:120,c4=connectors.length>=4?180:connectors.length>=2?160:120,c5=agent&&action?180:agent||action?120:80;if(wc>=200)strengths.push(`Boa extensão: ${wc} palavras permitem desenvolver as ideias.`);if(pars>=4)strengths.push('A organização em parágrafos ajuda a separar introdução, desenvolvimento e conclusão.');if(connectors.length>=3)strengths.push(`Você usou conectivos como “${connectors.slice(0,3).join('”, “')}”, favorecendo a progressão.`);if(agent&&action)strengths.push(`A proposta de intervenção apresenta agente (${agent}) e ação (${action}).`);if(tm.hits.length)strengths.push(`O texto dialoga com palavras centrais do tema, como ${tm.hits.slice(0,3).join(', ')}.`);if(wc<250)tips.push('Amplie o desenvolvimento com explicações, causas, consequências e exemplos concretos.');if(pars<4)tips.push('Organize o texto em introdução, dois desenvolvimentos e conclusão.');if(connectors.length<3)tips.push('Varie conectivos entre frases e parágrafos para deixar a progressão mais clara.');if(!agent||!action)tips.push('Detalhe a intervenção com agente, ação, meio de execução, finalidade e detalhamento.');if(weakTheme)tips.push(`A relação com o tema ainda está superficial. Retome explicitamente “${state.theme}” na tese e nos argumentos.`);if(sentences.some(x=>x.split(/\s+/).length>38))errors.push('Há períodos muito longos; divida algumas frases para melhorar clareza e pontuação.');if(pars<3)errors.push('Pouca divisão em parágrafos prejudica a organização argumentativa.');if(connectors.length<2)errors.push('Há pouca variedade de mecanismos coesivos entre as ideias.');const comp=[c1,c2,c3,c4,c5],total=comp.reduce((a,b)=>a+b,0);return{total,comp,tips,strengths:strengths.length?strengths:['Há uma estrutura dissertativo-argumentativa identificável.'],errors,offTopic:false,themeCoverage:Math.round(tm.ratio*100)}}
function essayResult(r){const names=['Norma-padrão','Tema e repertório','Argumentação','Coesão','Intervenção'];return `<div class="essay-result">${r.offTopic?`<div class="theme-alert danger"><b>⚠️ Fuga ao tema identificada</b><p>A redação não responde ao tema escolhido. No ENEM, fuga total ao tema zera a prova.</p></div>`:`<div class="theme-alert ok"><b>🎯 Aderência ao tema</b><p>Compatibilidade estimada: ${r.themeCoverage}%.</p></div>`}<div class="essay-score"><span>Nota estimada</span><strong>${r.total}</strong><small>/1000</small></div>${names.map((n,i)=>`<details class="competence" ${i===1?'open':''}><summary><span>${n}</span><b>${r.comp[i]}/200</b></summary><div class="progress"><i style="width:${r.comp[i]/2}%"></i></div></details>`).join('')}<div class="feedback-grid"><section class="feedback-box success"><h3>✅ O que você fez bem</h3>${r.strengths.length?r.strengths.map(t=>`<p>• ${esc(t)}</p>`).join(''):'<p>• Continue praticando para consolidar os pontos fortes.</p>'}</section><section class="feedback-box warn"><h3>🎯 O que melhorar</h3>${r.tips.map(t=>`<p>• ${esc(t)}</p>`).join('')}</section>${r.errors.length?`<section class="feedback-box error"><h3>🔎 Erros identificados</h3>${r.errors.map(t=>`<p>• ${esc(t)}</p>`).join('')}</section>`:''}</div><button class="caramelo-ask" data-action="ask-caramelo-essay">🐶 Conversar com o Prof. Caramelo sobre esta redação →</button></div>`}
'''
s,n=re.subn(r'function scoreEssay\(text\)\{.*?\}\nfunction essayResult\(r\)\{.*?\}\nfunction themePanel',essay+'\nfunction themePanel',s,count=1,flags=re.S)
if n!=1: raise SystemExit('essay patch failed')

review=r'''function reviewExplanation(q,answer){const topic=inferTopic(q),letter=String.fromCharCode(65+q.c),correct=questionText(q.a[q.c]),chosen=answer==null?'nenhuma alternativa':questionText(q.a[answer]);if(answer===q.c)return `Você acertou porque a alternativa ${letter} responde diretamente ao comando usando o conceito de ${topic}. Tente explicar com suas palavras por que “${correct.slice(0,180)}” resolve o problema; isso ajuda a fixar a habilidade.`;return `Você marcou ${answer==null?'nenhuma alternativa':String.fromCharCode(65+answer)}, mas a correta é ${letter}. Compare a sua escolha (“${chosen.slice(0,150)}”) com a correta (“${correct.slice(0,180)}”). A habilidade central é ${questionSkill(q)}. Na próxima tentativa, destaque no enunciado os dados e a ação pedida antes de avaliar as alternativas.`}
function reviewHtml(items,answers){return `<div class="page-head"><div><span class="eyebrow">ANÁLISE</span><h1>Revisão do simulado</h1><p class="muted">Abra cada questão para ver a explicação completa.</p></div><button class="ghost" data-action="new-quiz">Voltar</button></div><div class="review-list">${items.map((q,i)=>{const ok=answers[i]===q.c,topic=inferTopic(q);return `<details class="review-card ${ok?'ok':'no'}"><summary><span>${ok?'✅':'❌'} Questão ${i+1}</span><b>${q.area} • ${topic}</b></summary><div class="review-body"><h3>${questionText(q.q)}</h3><div class="review-tags"><span>📚 ${topic}</span><span>🎯 ${questionSkill(q)}</span></div><p><b>Sua resposta:</b> ${answers[i]==null?'Não respondida':`${String.fromCharCode(65+answers[i])} — ${questionText(q.a[answers[i]])}`}</p><p><b>Correta:</b> ${String.fromCharCode(65+q.c)} — ${questionText(q.a[q.c])}</p><div class="review-explain"><b>${ok?'Por que você acertou':'Como corrigir o raciocínio'}</b><p>${esc(reviewExplanation(q,answers[i]))}</p></div></div></details>`}).join('')}</div>`}'''
s,n=re.subn(r'function reviewExplanation\(q,answer\)\{.*?\}\nfunction reviewHtml\(items,answers\)\{.*?\}',review,s,count=1,flags=re.S)
if n!=1: raise SystemExit('review patch failed')

quiz=r'''function quizView(){const q=quiz.items[quiz.i],ans=quiz.answers[quiz.i],checked=quiz.checked[quiz.i];const images=(q.files||[]).map(f=>typeof f==='string'?f:(f.url||f.path||'')).filter(Boolean);return `<div class="quiz-top"><button class="close" data-action="exit-quiz">✕</button><div><span>${esc(quiz.title)}</span><b>Questão ${quiz.i+1} de ${quiz.items.length}</b></div><div class="qprogress"><i style="width:${(quiz.i+1)/quiz.items.length*100}%"></i></div></div><article class="question-card"><span class="eyebrow">${q.year?'ENEM '+q.year:(q.topic||q.area)}</span>${q.context?`<div class="question-context">${questionText(q.context).replace(/\n/g,'<br>')}</div>`:''}${images.map(src=>`<figure class="question-figure"><button class="image-zoom" data-action="zoom-image" data-src="${esc(src)}"><img class="question-img" src="${esc(src)}" alt="Imagem da questão"><span>🔎 Toque para ampliar</span></button><figcaption>${esc((src.split('/').pop()||'imagem').slice(0,45))}</figcaption></figure>`).join('')}<h2 class="question-command">${questionText(q.q)}</h2><div class="answers">${q.a.map((x,i)=>`<button data-answer="${i}" class="${ans===i?'selected':''} ${checked&&i===q.c?'correct':''} ${checked&&ans===i&&i!==q.c?'wrong':''}" ${checked?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${questionText(x)}</span></button>`).join('')}</div>${checked?`<div class="feedback ${ans===q.c?'good':'bad'}"><h3>${ans===q.c?'✅ Resposta correta!':'❌ Resposta incorreta'}</h3>${ans!==q.c?`<p><b>Resposta correta:</b> ${String.fromCharCode(65+q.c)} — ${questionText(q.a[q.c])}</p>`:''}<p>${esc(reviewExplanation(q,ans))}</p></div>`:''}</article><div class="quiz-bar">${!checked?`<button class="primary" data-action="confirm-answer" ${ans==null?'disabled':''}>Confirmar resposta</button>`:`<button class="primary" data-action="next-question">${quiz.i===quiz.items.length-1?'Ver resultado':'Próxima questão →'}</button>`}</div><div id="imageModal"></div>`}'''
s,n=re.subn(r'function quizView\(\)\{.*?\}\nfunction finishQuiz',quiz+'\nfunction finishQuiz',s,count=1,flags=re.S)
if n!=1: raise SystemExit('quiz patch failed')

prof=r'''function localProfAnswer(text){const previous=state.chat.filter(m=>m.role==='user').slice(-2,-1)[0]?.text||'';const combined=(previous+' '+text).toLowerCase();const weak=state.selfReportedWeak||AREAS.slice().sort((a,b)=>state.difficultyScores[a]-state.difficultyScores[b])[0];if(/como (usar|funciona)|usar o app|aplicativo/.test(combined))return 'No Início você recebe recomendações; em Simulados escolhe áreas e quantidade; em Desempenho acompanha evolução; e em Redação treina e recebe feedback. Durante uma questão, feche pelo X se quiser sair. 🐶📱✨';if(/matem|equação|porcent|geometr|funç/.test(combined))return `Para melhorar em Matemática, faça: 1) identifique o conteúdo da questão; 2) anote os dados; 3) escolha a fórmula ou estratégia; 4) resolva sem olhar alternativas; 5) compare e revise o erro. ${weak==='Matemática'?'Como Matemática é seu foco escolhido, ela terá mais questões nos treinos personalizados.':'Vou manter seu foco em '+weak+' e incluir revisão frequente de Matemática.'} 📐🐶`;if(/redação|redacao|tese|argument|interven/.test(combined))return `Na redação sobre “${state.theme}”, confirme primeiro que a tese responde exatamente ao tema. Depois use dois argumentos diferentes e finalize com agente, ação, meio e finalidade. Se a avaliação marcar fuga ao tema, reescreva a tese antes de mexer no restante. ✍️🎯🐶`;if(/desempenho|melhorar|dificuldade|ponto fraco|foco/.test(combined))return `Seu foco escolhido é ${weak}. Eu não vou trocar essa escolha silenciosamente. O painel pode mostrar outro ponto fraco detectado pelos acertos, mas ele entra como reforço secundário. 📊🐾`;if(/hist[oó]ria|humanas|geografia|sociologia|filosofia/.test(combined))return 'Em Humanas, leia o comando antes do texto, identifique período/contexto e procure relações de causa, consequência e interesse social. Nas alternativas, elimine as que extrapolam a fonte. 🌎📚🐶';if(/natureza|biologia|qu[ií]mica|f[ií]sica/.test(combined))return 'Em Natureza, identifique primeiro o fenômeno e as grandezas envolvidas. Depois escolha o conceito ou fórmula e confira unidade e ordem de grandeza antes de marcar. 🧪🔬🐶';if(/linguagem|portugu|interpreta|texto/.test(combined))return 'Em Linguagens, leia o comando primeiro e volte ao texto procurando evidência. Compare o efeito de sentido de cada alternativa com um trecho concreto, não apenas com o tema geral. 📖✨🐶';return `Posso te explicar passo a passo. Seu foco principal continua sendo ${weak}. Diga qual matéria, questão ou parte do app você quer entender e eu continuo daqui. 🐶📚✨`}
async function sendProf(){const input=document.querySelector('#profInput'),text=input?.value.trim();if(!text)return;state.chat.push({role:'user',text});save();renderProfPanel();const typing=document.querySelector('#profTyping');if(typing)typing.innerHTML='<div class="msg assistant typing">Pensando na melhor forma de te explicar… 🐶💭✨</div>';const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),4500);try{const r=await fetch('https://estudai-app.vercel.app/api/prof-caramelo',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({message:text,context:{selfReportedWeak:state.selfReportedWeak,difficultyScores:state.difficultyScores,history:state.history.slice(-5).map(h=>({area:h.area,correct:h.correct,total:h.total})),theme:state.theme,previousMessages:state.chat.slice(-5)}})});clearTimeout(timer);if(!r.ok)throw new Error('server');const d=await r.json();state.chat.push({role:'assistant',text:friendlyAnswer(d.answer||localProfAnswer(text))})}catch(e){clearTimeout(timer);state.chat.push({role:'assistant',text:localProfAnswer(text)})}save();renderProfPanel()}'''
s,n=re.subn(r'function localProfAnswer\(text\)\{.*?\}\nfunction friendlyAnswer',prof+'\nfunction friendlyAnswer',s,count=1,flags=re.S)
if n!=1: raise SystemExit('prof local patch failed')
s,n=re.subn(r'async function sendProf\(\)\{.*?\}\nfunction renderProfPanel',lambda m:'',s,count=0)
# restore sendProf only if duplicate old function remains
if 'async function sendProf(){const input=document.querySelector' not in s:
    raise SystemExit('sendProf replacement missing')

# Insert image zoom actions before generic save-profile branch.
s=s.replace("else if(a==='save-profile')", "else if(a==='zoom-image'){const src=b.dataset.src;const m=document.querySelector('#imageModal');if(m)m.innerHTML=`<div class=\"image-modal\" data-action=\"close-image\"><div><button data-action=\"close-image\">✕</button><img src=\"${esc(src)}\"></div></div>`;bind()}else if(a==='close-image'){const m=document.querySelector('#imageModal');if(m)m.innerHTML=''}else if(a==='save-profile')",1)

# More descriptive metric source label.
s=s.replace('</section><section class="priority-card"><h2>🐶 Prof. Caramelo recomenda</h2>', '</section><p class="metric-source">ℹ️ Taxa geral e desempenho por área usam apenas simulados e treinos concluídos; o diagnóstico inicial aparece como estimativa quando ainda não há tentativas.</p><section class="priority-card"><h2>🐶 Prof. Caramelo recomenda</h2>',1)

p.write_text(s,encoding='utf-8')

css=pathlib.Path('styles.css')
c=css.read_text(encoding='utf-8')
c+=r'''
/* v2.2 full video checklist */
.topbar{padding-top:max(10px,env(safe-area-inset-top));min-height:76px}.brand img{image-rendering:auto}.focus-title{align-items:center;gap:12px}.focus-title h2{white-space:nowrap;font-size:clamp(1.55rem,6vw,2.2rem)}.focus-title span{font-size:.95rem}.focus-note{display:flex;flex-direction:column;gap:5px;margin:-4px 0 16px;padding:13px 16px;border-radius:18px;background:linear-gradient(110deg,#e8f5ff,#effaf2,#fff8d7);color:#17314c}.question-card{padding-bottom:104px}.question-context,.question-command{font-size:1.06rem!important;line-height:1.62!important;color:#172237!important}.question-context{font-weight:400!important;white-space:normal}.question-command{font-weight:700!important;margin-top:18px}.question-card .answers button span{font-size:1rem;line-height:1.45}.question-figure{margin:18px 0}.image-zoom{width:100%;border:1px solid #d9e3e8;background:#fff;border-radius:18px;padding:10px;box-shadow:none}.image-zoom img{display:block;width:100%;max-height:420px;object-fit:contain;border-radius:12px}.image-zoom span{display:block;margin-top:7px;font-size:.78rem;color:#617080}.question-figure figcaption{font-size:.68rem;color:#87939e;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px}.image-modal{position:fixed;inset:0;z-index:500;background:rgba(5,20,35,.88);display:grid;place-items:center;padding:20px}.image-modal>div{position:relative;width:min(100%,760px)}.image-modal img{width:100%;max-height:86vh;object-fit:contain;background:white;border-radius:18px}.image-modal button{position:absolute;right:10px;top:10px;z-index:2;width:44px;height:44px;border:0;border-radius:50%;background:#fff;font-size:1.35rem}.quiz-bar{z-index:130}.review-list{display:grid;gap:12px}.review-card{padding:0!important;overflow:hidden}.review-card summary{cursor:pointer;list-style:none;padding:18px;display:flex;justify-content:space-between;gap:12px;align-items:center}.review-card summary::-webkit-details-marker{display:none}.review-card summary b{font-size:.85rem;color:#596779;text-align:right}.review-body{padding:0 18px 18px;border-top:1px solid #edf0f1}.feedback-grid{display:grid;gap:12px;margin-top:16px}.feedback-box{padding:16px;border-radius:18px}.feedback-box.success{background:#eaf8ef;border:1px solid #b9e6c8}.feedback-box.warn{background:#fff8da;border:1px solid #f1d877}.feedback-box.error{background:#fff0f0;border:1px solid #efc2c2}.feedback-box h3{margin:0 0 8px}.feedback-box p{margin:6px 0;line-height:1.45}.theme-alert{padding:14px 16px;border-radius:18px;margin:16px 0}.theme-alert.ok{background:#eaf7ee;border:1px solid #b7e0c2}.theme-alert.danger{background:#fff0f0;border:1px solid #efb9b9}.competence summary{display:flex;justify-content:space-between;align-items:center;cursor:pointer}.metric-source{font-size:.82rem;color:#69798b;line-height:1.45;margin:10px 20px 20px}.prof-panel .prof-head img,.streak-banner img,.diag-top img,.onboard-card img,.diag-done img,.plan-loading img{object-fit:cover;image-rendering:auto}.splash img{image-rendering:auto;animation:splashIn .65s ease both}.splash h1,.splash p{animation:splashText .7s .15s ease both}.splash.exit{animation:splashOut .42s ease forwards}@keyframes splashIn{from{opacity:0;transform:scale(.84) translateY(14px)}to{opacity:1;transform:scale(1) translateY(0)}}@keyframes splashText{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}@keyframes splashOut{to{opacity:0;transform:scale(1.03)}}
'''
css.write_text(c,encoding='utf-8')
print('v2.2 checklist fixes applied')
